def bench(self, launcher, *args, with_profiler=False, **kwargs):
    """Measure the performance of a given launcher."""
    # we don't skip configs with spilled registers when auto-tuning custom
    # (user-written) Triton kernels, as (i) we don't have any knowledge or
    # control over the kernel code; (ii) there is empirical evidence that
    # for some (complicated) custom Triton kernels, a register-spilling
    # config may yield the best latency.
    if (
        not self.custom_kernel
        and launcher.n_spills is not None
        and launcher.n_spills
        > self.inductor_meta.get("spill_threshold", 32 if torch.version.hip else 16)
    ):
        log.debug(
            "Skip config %s because of register spilling: %d",
            launcher.config,
            launcher.n_spills,
        )
        self.benchmark_failure_reasons[launcher] = (
            BenchmarkFailureReason.REGISTER_SPILLING
        )
        return float("inf")

    device_interface = self.get_device_interface()
    stream = device_interface.get_raw_stream(device_interface.current_device())

    cpu_copies = self.copy_args_to_cpu_if_needed(*args, **kwargs)

    def kernel_call():
        cloned_args, cloned_kwargs = self.maybe_clone_args(
            cpu_copies, *args, **kwargs
        )
        kernel_name = self.inductor_meta.get("kernel_name", "triton kernel")
        # reset to zero before evaluating any config
        self.reset_to_zero_args(*args, **kwargs)
        if autograd_profiler._is_profiler_enabled:
            profiler_kwargs = self.get_profiler_kwargs(stream, launcher)
            with torch._C._profiler._RecordFunctionFast(
                kernel_name,
                cloned_args,
                profiler_kwargs,
            ):
                try:
                    launcher(
                        *cloned_args,
                        **cloned_kwargs,
                        stream=stream,
                    )
                except Exception as e:
                    if isinstance(e, TypeError):
                        self._check_launcher_call_args(launcher, cloned_args)
                    log.error(
                        "Failed during launch %s with config: %s (num_warps=%s, num_stages=%s, kwargs=%s)",
                        kernel_name,
                        launcher.config,
                        launcher.config.num_warps,
                        launcher.config.num_stages,
                        launcher.config.kwargs,
                    )
                    raise

        else:
            try:
                launcher(
                    *cloned_args,
                    **cloned_kwargs,
                    stream=stream,
                )
            except Exception as e:
                if isinstance(e, TypeError):
                    self._check_launcher_call_args(launcher, cloned_args)
                log.error(
                    "Failed during launch %s with config: %s (num_warps=%s, num_stages=%s, kwargs=%s)",
                    kernel_name,
                    launcher.config,
                    launcher.config.num_warps,
                    launcher.config.num_stages,
                    launcher.config.kwargs,
                )
                raise
        self.restore_args_from_cpu(cpu_copies)

    # only use profiler when not already in a profiler instance
    if with_profiler and not autograd_profiler._is_profiler_enabled:
        from torch._inductor.utils import do_bench_using_profiling

        return do_bench_using_profiling(kernel_call, warmup=10, rep=40)

    benchmark_kwargs = (
        {}
        if self.device_props.type == "cpu"
        else {"rep": 40, "is_vetted_benchmarking": True}
    )
    result = benchmarker.benchmark(
        fn=kernel_call,
        device=self.device_props.type,
        **benchmark_kwargs,  # type: ignore[arg-type]
    )
    # benchmarker.benchmark() only returns float("inf") when catching an
    # "invalid configuration" exception - all other exceptions are re-raised.
    # Therefore, if result is inf here, it must be due to invalid config.
    if result == float("inf"):
        self.benchmark_failure_reasons[launcher] = (
            BenchmarkFailureReason.INVALID_CONFIG
        )
    return result

def _register_custom_backend_with_heuristics(self, device):
    path_to_ext_heuristics = str(
        Path(__file__).parent / "extension_backends" / "triton"
    )
    # Add the path to sys.path in the parent process so that the
    # ExtensionCachingAutotuner class (defined in extension_triton_heuristics)
    # can be resolved when the compiled kernel is unpickled from the
    # compile subprocess back into the parent process.
    if path_to_ext_heuristics not in sys.path:
        sys.path.append(path_to_ext_heuristics)
        self.addCleanup(sys.path.remove, path_to_ext_heuristics)

    class ExtensionTritonKernel(codegen.triton.TritonKernel):
        @classmethod
        @functools.lru_cache(None)
        def gen_common_triton_imports(cls) -> str:
            default_imports = super().gen_common_triton_imports()
            custom_imports = IndentedBuffer()
            custom_imports.splice(default_imports)

            custom_imports.splice("""
                import extension_triton_heuristics as triton_heuristics
            """)
            return custom_imports

        @classmethod
        def triton_meta_common(cls) -> dict[str, Any]:
            triton_meta = super().triton_meta_common()
            triton_meta[EXTENSION_TRITON_META_FIELD] = True
            return triton_meta

    class ExtensionTritonScheduling(codegen.triton.TritonScheduling):
        kernel_type = ExtensionTritonKernel

    class ExtensionPythonWrapperCodegen(PythonWrapperCodegen):
        @classmethod
        def _get_triton_info_kernel_cls(cls) -> type[codegen.triton.TritonKernel]:
            return ExtensionTritonKernel

        @staticmethod
        def create(
            is_subgraph: bool,
            subgraph_name: str | None,
            parent_wrapper: PythonWrapperCodegen | None,
            partition_signatures: ir.GraphPartitionSignature | None = None,
        ):
            if is_subgraph:
                if subgraph_name is None:
                    raise AssertionError
                if parent_wrapper is None:
                    raise AssertionError
                return PythonWrapperCodegen.create(
                    subgraph_name, parent_wrapper, partition_signatures
                )
            return ExtensionPythonWrapperCodegen()

    register_backend_for_device(
        device, ExtensionTritonScheduling, ExtensionPythonWrapperCodegen
    )

def is_big_gpu(index_or_device: int | torch.device = 0) -> bool:
    if isinstance(index_or_device, torch.device):
        device = index_or_device
    else:
        device = torch.device(get_gpu_type(), index_or_device)

    prop = DeviceProperties.create(device)

    # SM logic is not relevant to ROCm gpus
    # Arbitrarily skipping the older models
    if torch.version.hip:
        assert prop.major is not None
        if prop.major < 9 or prop.major == 10:
            log.warning("GPU arch does not support max_autotune_gemm mode usage")
            return False
        return True

    min_sms = 16 if device.type == "xpu" else 68  # 3080
    avail_sms = prop.multi_processor_count
    if avail_sms < min_sms:
        log.warning(
            "Not enough SMs to use max_autotune_gemm mode",
            extra={"min_sms": min_sms, "avail_sms": avail_sms},
        )
        return False
    return True

def _ensure_fp4_dtype_registered():
    """Patch cutlass_api to handle torch.float4_e2m1fn_x2 -> cutlass.Float4E2M1FN.

    NOTE: cutlass_api doesn't natively map this dtype. We patch the lookup function
    in-place so all callers (including TensorWrapper) pick up the change.
    Remove once cutlass_api adds native FP4 support.
    """
    import cutlass_api.utils

    try:
        cutlass_api.utils.cutlass_type_from_torch_type(torch.float4_e2m1fn_x2)
    except (KeyError, AttributeError):
        import cutlass

        _orig = cutlass_api.utils.cutlass_type_from_torch_type

        def _patched(dtype):
            if dtype == torch.float4_e2m1fn_x2:
                return cutlass.Float4E2M1FN
            return _orig(dtype)

        cutlass_api.utils.cutlass_type_from_torch_type = _patched

def slowTest(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        if not TEST_WITH_SLOW:
            raise unittest.SkipTest("test is slow; run with PYTORCH_TEST_WITH_SLOW to enable test")
        else:
            fn(*args, **kwargs)
    wrapper.__dict__['slow_test'] = True
    return wrapper

def use_triton_template(
    layout, *, enable_int32: bool = False, enable_float8: bool = False
) -> bool:
    from torch._inductor.codegen.common import BackendFeature, has_backend_feature
    from torch._inductor.utils import _use_autotune_backend, is_gpu

    layout_dtypes = [torch.float16, torch.bfloat16, torch.float32]
    if enable_int32:
        layout_dtypes = [torch.float16, torch.bfloat16, torch.float32, torch.int32]
    if enable_float8:
        layout_dtypes.extend([torch.float8_e4m3fn, torch.float8_e5m2])
    return (
        (
            (
                is_gpu(layout.device.type)
                and _use_template_for_npu(layout, layout_dtypes)
            )
            or (layout.device.type == "cpu" and layout.dtype in layout_dtypes)
        )
        and inductor_config.max_autotune
        and _use_autotune_backend("TRITON")
        and has_backend_feature(layout.device, BackendFeature.TRITON_TEMPLATES)
    )

def has_triton_tma_device() -> bool:
    if has_triton_package():
        import torch

        if (
            torch.cuda.is_available()
            and torch.cuda.get_device_capability() >= (9, 0)
            and not torch.version.hip
        ) or torch.xpu.is_available():
            # old API
            try:
                from triton.language.extra.cuda import (  # noqa: F401
                    experimental_device_tensormap_create1d,
                    experimental_device_tensormap_create2d,
                )

                return True
            except ImportError:
                pass

            # new API
            try:
                from triton.language import make_tensor_descriptor  # noqa: F401

                return True
            except ImportError:
                pass

    return False
